function currentOppRoute() { const parts = window.location.pathname.split('/').filter(Boolean); const index = parts.findIndex((part, position) => part === 'painel-ar' && parts[position + 1] === '205'); if (index < 0) return { active: false, view: 'list', id: '' }; const tail = parts.slice(index + 2); if (tail[0] === 'lead' && tail[1] === 'novo') return { active: true, view: 'lead-new', id: '' }; if (tail[0] === 'oportunidade' && tail[1] === 'novo') return { active: true, view: 'opp-new', id: '' }; if (tail[0] === 'oportunidade' && tail[2] === 'editar') return { active: true, view: 'opp-edit', id: tail[1] || '' }; if (tail[0] === 'oportunidade' && tail[1]) return { active: true, view: 'opp-detail', id: tail[1] }; return { active: true, view: 'list', id: '' }; }
function oppPath(suffix = '') { const hasHub = window.location.pathname.split('/').filter(Boolean)[0] === 'hub'; return `${hasHub ? '/hub' : ''}/painel-ar/205${suffix ? `/${suffix}` : ''}`; }
