function relatedPjOpp(id) { const records = window.crm2PjGetMockItems?.() || []; return records.find((item) => item.id === id) || null; }
function pjAddressOpp(pj) { if (!pj) return ''; return [pj.cep, pj.logradouro || pj.endereco, pj.numero, pj.bairro, pj.cidadeEstado, pj.uf].filter((value) => String(value || '').trim()).join(', '); }
function leadLabel(lead) { return upperOpp(lead ? (lead.tipo === 'PJ' ? lead.razaoSocial : lead.nome) : 'Lead provisório'); }
function opportunityLabel(opp) { const lead = leadById(opp.leadId); const pf = relatedPfOpp(opp.pfId); const pj = relatedPjOpp(opp.pjId); return upperOpp(lead ? leadLabel(lead) : pf?.nome || pj?.razaoSocial || 'Registro relacionado'); }
function totalOpp(opp) { return (opp.itens || []).reduce((total, item) => total + (Number(item.quantidade || 0) * Number(String(item.valorUnitario || '0').replace('.', '').replace(',', '.'))), 0); }
function statusClassOpp(value = '') { return normOpp(value).replace(/\s+/g, '-'); }
