function pfOppFormData(pfId = '', fallback = {}) { const pf = relatedPfOpp(pfId); if (!pf) return { pfNome: upperOpp(fallback.pfNome), pfCpf: fallback.pfCpf ? maskCpfOpp(fallback.pfCpf) : '', pfNascimento: fallback.pfNascimento || '', pfEmail: fallback.pfEmail || '', pfTelefone: fallback.pfTelefone ? maskPhoneOpp(fallback.pfTelefone) : '', pfParceiro: fallback.pfParceiro || '', pfOrigem: fallback.pfOrigem || '' }; return { pfNome: upperOpp(pf.nome), pfCpf: pf.cpf ? maskCpfOpp(pf.cpf) : '', pfNascimento: pf.nascimento ? dateLabelOpp(pf.nascimento) : '', pfEmail: pf.email || '', pfTelefone: pf.telefone ? maskPhoneOpp(pf.telefone) : '', pfParceiro: pf.parceiro || '', pfOrigem: pf.origem || '' }; }
function productPriceOpp(product = '') { return OPPORTUNITY_PRODUCT_PRICES[product] || ''; }
function oppReadonlyField({ label, name, value = '', editable = false }) { const readonly = editable ? '' : ' readonly aria-readonly="true"'; const event = editable && name === 'pfNome' ? ' oninput="crm2OportunidadesFormatName(this)"' : ''; return `<label class="crm2-opp-derived-field"><span>${escapeOpp(label)}</span><input class="config-input crm2-opp-pf-auto-field" data-pf-auto-field="true" name="${name}" value="${attrOpp(name === 'pfNome' ? upperOpp(value) : value)}" placeholder="—"${readonly}${event}></label>`; }
function oppEditablePfField({ label, name, value = '', type = 'text' }) { const mask = name === 'pfTelefone' ? ' oninput="crm2OportunidadesFormatPhone(this); crm2OportunidadesSyncPfContact(\'pfTelefone\', this.value)"' : ` oninput="crm2OportunidadesSyncPfContact('${name}', this.value)"`; return `<label><span>${escapeOpp(label)}</span><input class="config-input" name="${name}" type="${type}" value="${attrOpp(value)}"${mask}></label>`; }
function renderOppPfFields(draft) { const data = pfOppFormData(draft.pfId, draft); const manual = !draft.pfId; return `<input type="hidden" name="pfId" value="${attrOpp(draft.pfId || '')}"><input type="hidden" name="origem" value="${attrOpp(draft.origem || data.pfOrigem || '')}"><label class="crm2-opp-derived-field crm2-opp-cpf-match-field"><span>CPF</span><div class="crm2-opp-cpf-search-control"><input class="config-input" name="pfCpf" value="${attrOpp(data.pfCpf)}" placeholder="000.000.000-00" inputmode="numeric" maxlength="14" oninput="crm2OportunidadesFormatPfCpf(this)" onblur="crm2OportunidadesMatchPf(this.value)"><button class="icon-btn crm2-opp-cpf-search" type="button" title="Buscar CPF" aria-label="Buscar CPF" onclick="crm2OportunidadesMatchPf(this.closest('.crm2-opp-cpf-search-control').querySelector('[name=pfCpf]').value)"><i data-lucide="search" aria-hidden="true"></i></button></div><small class="crm2-opp-cpf-match-message" aria-live="polite" ${manual && data.pfCpf ? '' : 'hidden'}>CPF sem cadastro</small></label>${oppReadonlyField({ label: 'Nome (PF Vinculada)', name: 'pfNome', value: data.pfNome, editable: manual })}${oppReadonlyField({ label: 'Nascimento', name: 'pfNascimento', value: data.pfNascimento, editable: manual })}${oppEditablePfField({ label: 'E-mail', name: 'pfEmail', value: data.pfEmail, type: 'email' })}${oppEditablePfField({ label: 'Telefone', name: 'pfTelefone', value: data.pfTelefone })}${oppReadonlyField({ label: 'Parceiro de Indicação', name: 'pfParceiro', value: data.pfParceiro, editable: manual })}`; }
function titleFromOppValues(values) { const pf = relatedPfOpp(values.pfId); if (pf?.nome) return pf.nome; const lead = leadById(values.leadId); if (lead) return leadLabel(lead); const pj = relatedPjOpp(values.pjId); return pj?.razaoSocial || values.titulo || 'Oportunidade'; }
function syncPfContactOpp(values) { const pf = relatedPfOpp(values.pfId); if (!pf) return; if (Object.prototype.hasOwnProperty.call(values, 'pfEmail')) pf.email = String(values.pfEmail || ''); if (Object.prototype.hasOwnProperty.call(values, 'pfTelefone')) pf.telefone = String(values.pfTelefone || ''); }
function renderOppFormHistory(opp) { if (opp) return renderOppTimelineColumn(opp); return '<section class="crm2-pf-timeline-column crm2-opp-timeline-column crm2-opp-form-history-placeholder" aria-labelledby="crm2-opp-form-history-title"><div class="hub-form-section-title crm2-pf-timeline-title"><div class="crm2-pf-timeline-heading"><strong id="crm2-opp-form-history-title">Histórico</strong></div></div><div class="crm2-pessoas-state crm2-timeline-state" role="status"><strong>Histórico disponível após o cadastro.</strong><span>As interações da oportunidade aparecerão aqui.</span></div></section>'; }
function renderOppItemForm(draft, pjOptions) { return `<div class="crm2-opp-items-form"><div class="crm2-opp-items-form-header"><strong>Produto(s)</strong><button class="secondary-btn" type="button" onclick="crm2OportunidadesAddItem()">Incluir</button></div><div class="crm2-opp-items-sheet-wrap"><table class="crm2-opp-items-sheet"><thead><tr><th>Pedido</th><th>Produto</th><th>PJ vinculada</th><th>Ações</th></tr></thead><tbody>${(draft.itens || []).map((item, index) => { const product = item.produto || ''; const price = productPriceOpp(product); const pedido = item.numeroPedido || item.pedido || ''; const pjId = item.pjId || draft.pjId || ''; const pj = relatedPjOpp(pjId); const address = pjAddressOpp(pj); const cnpj = maskCnpjOpp(pj?.cnpj); return `<tr><td><div class="crm2-opp-order-cell"><input class="config-input" name="itemOrder-${index}" value="${attrOpp(pedido)}" placeholder="Pedido"><small class="crm2-opp-order-price-pill" data-item-price>${escapeOpp(price)}</small></div></td><td><select class="config-input" name="itemProduct-${index}" onchange="crm2OportunidadesSyncItemPrice(this)"><option value="">Selecione</option>${OPPORTUNITY_PRODUCTS.map((option) => `<option value="${attrOpp(option)}" ${product === option ? 'selected' : ''}>${escapeOpp(option)}</option>`).join('')}</select></td><td><div class="crm2-opp-pj-cell"><select class="config-input" name="itemPj-${index}" onchange="crm2OportunidadesUpdateItemPj(this)"><option value="">Selecione</option>${pjOptions.map((option) => `<option value="${attrOpp(option.value)}" ${String(option.value) === String(pjId) ? 'selected' : ''}>${escapeOpp(option.label)}</option>`).join('')}</select><div class="crm2-opp-pj-meta-row"><small class="crm2-opp-pj-cnpj-pill" data-pj-cnpj ${cnpj === '—' ? 'hidden' : ''}>${escapeOpp(cnpj)}</small><small class="crm2-opp-pj-address-pill" data-pj-address ${address ? '' : 'hidden'}>${escapeOpp(address)}</small></div></div></td><td>${(draft.itens || []).length > 1 ? `<button class="secondary-btn" type="button" onclick="crm2OportunidadesRemoveItem(${index})">Remover</button>` : '—'}</td></tr>`; }).join('')}</tbody></table></div></div>`; }
function resetOppForm() { crm2OportunidadesState.formMode = ''; crm2OportunidadesState.detailId = ''; crm2OportunidadesState.inlineEditingId = ''; crm2OportunidadesState.draft = {}; crm2OportunidadesState.errors = {}; }

function renderOppState() { const copy = { loading: ['Carregando oportunidades...', 'Estado simulado para homologação.'], error: ['Não foi possível carregar oportunidades.', 'Erro simulado. Nenhuma integração externa foi acionada.'], empty: ['Nenhuma oportunidade cadastrada.', 'A lista mockada ainda não possui negociações.'] }[crm2OportunidadesState.listState]; if (!copy) return ''; return `<div class="crm2-pessoas-state crm2-opp-state ${crm2OportunidadesState.listState === 'error' ? 'is-error' : ''}" role="${crm2OportunidadesState.listState === 'error' ? 'alert' : 'status'}"><strong>${copy[0]}</strong><span>${copy[1]}</span><button class="secondary-btn" type="button" onclick="crm2OportunidadesSetState('normal')">Voltar à lista</button></div>`; }
function currentOppFilterValues() { return { stage: crm2OportunidadesState.stageFilter, status: crm2OportunidadesState.statusFilter, responsible: crm2OportunidadesState.responsibleFilter, source: crm2OportunidadesState.sourceFilter, lossReason: crm2OportunidadesState.lossReasonFilter, dateFrom: crm2OportunidadesState.dateFrom, dateTo: crm2OportunidadesState.dateTo }; }
function hasOppFilters() { const values = currentOppFilterValues(); return Object.values(values).some(Boolean); }
function renderOppFilterModal() { if (!crm2OportunidadesState.filterModalOpen) return ''; const values = crm2OportunidadesState.filterDraft || currentOppFilterValues(); const responsibles = [...new Set(crm2OportunidadesState.opportunities.map((opp) => opp.responsavel))]; const optionList = (items, selected, emptyLabel) => `<option value="">${emptyLabel}</option>${items.map((item) => `<option value="${attrOpp(item)}" ${selected === item ? 'selected' : ''}>${escapeOpp(item)}</option>`).join('')}`; return `<div class="crm2-opp-filter-modal-backdrop" role="presentation" onclick="crm2OportunidadesCloseFilterModal(event)"><section id="crm2-opp-filter-modal" class="crm2-opp-filter-modal" role="dialog" aria-modal="true" aria-labelledby="crm2-opp-filter-modal-title" onclick="event.stopPropagation()"><header class="crm2-opp-filter-modal-header"><div><span class="ar-crm-phase1-kicker">ROTA 205 · FILTROS</span><h3 id="crm2-opp-filter-modal-title">Filtrar oportunidades</h3></div><button id="crm2-opp-filter-modal-close" class="icon-btn" type="button" title="Fechar filtros" aria-label="Fechar filtros" onclick="crm2OportunidadesCloseFilterModal()">×</button></header><form class="crm2-opp-filter-modal-form" onsubmit="crm2OportunidadesApplyModalFilters(event)"><label><span>Etapa</span><select class="config-input" name="stage" onchange="crm2OportunidadesSetFilterDraft(this.name, this.value)">${optionList(OPPORTUNITY_STAGES, values.stage, 'Todas as etapas')}</select></label><label><span>Status</span><select class="config-input" name="status" onchange="crm2OportunidadesSetFilterDraft(this.name, this.value)">${optionList(OPPORTUNITY_STATUSES, values.status, 'Todos os status')}</select></label><label><span>Responsável</span><select class="config-input" name="responsible" onchange="crm2OportunidadesSetFilterDraft(this.name, this.value)">${optionList(responsibles, values.responsible, 'Todos')}</select></label><label><span>Origem</span><select class="config-input" name="source" onchange="crm2OportunidadesSetFilterDraft(this.name, this.value)">${optionList(OPPORTUNITY_SOURCES, values.source, 'Todas')}</select></label><label><span>Motivo de perda</span><select class="config-input" name="lossReason" onchange="crm2OportunidadesSetFilterDraft(this.name, this.value)">${optionList(OPPORTUNITY_LOSS_REASONS, values.lossReason, 'Todos')}</select></label><label><span>Criada desde</span><input class="config-input" name="dateFrom" type="date" value="${attrOpp(values.dateFrom)}" onchange="crm2OportunidadesSetFilterDraft(this.name, this.value)"></label><label><span>Criada até</span><input class="config-input" name="dateTo" type="date" value="${attrOpp(values.dateTo)}" onchange="crm2OportunidadesSetFilterDraft(this.name, this.value)"></label><div class="crm2-opp-filter-modal-actions"><button class="secondary-btn" type="button" onclick="crm2OportunidadesClearFilterDraft()">Limpar</button><div><button class="secondary-btn" type="button" onclick="crm2OportunidadesCloseFilterModal()">Cancelar</button><button class="save-btn" type="submit">Aplicar filtros</button></div></div></form></section></div>`; }
function renderOppFilters() { const active = Boolean(crm2OportunidadesState.search || hasOppFilters()); const searchExpanded = Boolean(crm2OportunidadesState.searchExpanded); return `<form class="crm2-opp-filter-bar" role="search" onsubmit="event.preventDefault()" aria-label="Buscar e filtrar oportunidades"><div class="crm2-opp-view-toggle"><button class="secondary-btn ${crm2OportunidadesState.viewMode === 'table' ? 'active' : ''}" type="button" onclick="crm2OportunidadesSetView('table')">Tabela</button><button class="secondary-btn ${crm2OportunidadesState.viewMode === 'kanban' ? 'active' : ''}" type="button" onclick="crm2OportunidadesSetView('kanban')">Kanban</button></div><div class="crm2-opp-filter-actions">${crm2OportunidadesState.canCreate ? '<button class="save-btn crm2-opp-include-btn" type="button" onclick="crm2OportunidadesOpenCreate()">+ Oportunidade</button>' : ''}<button id="crm2-opp-filter-trigger" class="icon-btn ${hasOppFilters() ? 'is-active' : ''}" type="button" aria-haspopup="dialog" aria-expanded="${crm2OportunidadesState.filterModalOpen ? 'true' : 'false'}" aria-controls="crm2-opp-filter-modal" title="Filtrar oportunidades" aria-label="Filtrar oportunidades" onclick="crm2OportunidadesToggleFilterModal()"><i data-lucide="filter" aria-hidden="true"></i></button><div class="crm2-opp-search-control ${searchExpanded ? 'is-expanded' : ''}"><input class="config-input" type="search" aria-label="Buscar oportunidades" placeholder="Número, título, lead ou responsável" value="${attrOpp(crm2OportunidadesState.search)}" ${searchExpanded ? '' : 'hidden'} oninput="crm2OportunidadesSetSearch(this.value, this)" onfocusout="crm2OportunidadesHandleSearchBlur(event)" onkeydown="if (event.key === 'Enter') event.preventDefault()"><button class="icon-btn" type="button" title="Buscar" aria-label="Buscar" aria-expanded="${searchExpanded ? 'true' : 'false'}" onclick="crm2OportunidadesToggleSearch(this)"><i data-lucide="search" aria-hidden="true"></i></button></div>${active ? '<button class="icon-btn crm2-opp-clear-filter" type="button" onclick="crm2OportunidadesClearFilters()" title="Limpar filtros" aria-label="Limpar filtros">×</button>' : ''}</div></form>${renderOppFilterModal()}`; }
function renderOppTable(items) { return `<div class="ar-crm-phase1-table-wrap crm2-opp-table-wrap"><table class="ar-crm-phase1-table crm2-opp-table"><caption class="crm2-pessoas-table-caption">Oportunidades do CRM 2.0</caption><thead><tr><th>Nome</th><th>Próxima ação</th><th>Documento</th><th>Número do pedido</th><th>Parceiro de indicação</th></tr></thead><tbody>${items.map((opp) => { const presentation = opportunityPresentationOpp(opp); return `<tr><td><button class="crm2-opp-link crm2-opp-primary-value" type="button" onclick="crm2OportunidadesOpenDetail('${attrOpp(opp.id)}')" aria-label="Visualizar oportunidade de ${attrOpp(presentation.legalName)}">${escapeOpp(presentation.legalName)}</button>${presentation.isPj ? `<small class="crm2-opp-meta-pill">${escapeOpp(presentation.companyName)}</small>` : ''}</td><td>${renderNextActionEditorOpp(opp, presentation)}</td><td><strong class="crm2-opp-primary-value">${escapeOpp(presentation.cpf)}</strong>${presentation.cnpj !== '—' ? `<small class="crm2-opp-meta-pill">${escapeOpp(presentation.cnpj)}</small>` : ''}</td><td><strong class="crm2-opp-primary-value">${escapeOpp(opp.numero)}</strong>${stagePillOpp(opp.etapa)}</td><td>${escapeOpp(presentation.partner)}</td></tr>`; }).join('')}</tbody></table></div>`; }
function renderOppKanban(items) { return `<div class="crm2-opp-kanban">${OPPORTUNITY_STAGES.map((stage) => { const stageItems = items.filter((opp) => opp.etapa === stage); return `<section class="crm2-opp-kanban-column" aria-labelledby="crm2-opp-stage-${statusClassOpp(stage)}"><header><strong id="crm2-opp-stage-${statusClassOpp(stage)}">${escapeOpp(stage)}</strong><span>${stageItems.length}</span></header><div>${stageItems.length ? stageItems.map((opp) => `<article class="crm2-opp-card"><button class="crm2-opp-link" type="button" onclick="crm2OportunidadesOpenDetail('${attrOpp(opp.id)}')">${escapeOpp(opp.numero)}</button><strong>${escapeOpp(opp.titulo)}</strong><span>${escapeOpp(opportunityLabel(opp))}</span><small>${moneyOpp(opp.valorEstimado || totalOpp(opp))} · ${escapeOpp(opp.responsavel)}</small></article>`).join('') : '<p class="crm2-opp-kanban-empty">Nenhum registro</p>'}</div></section>`; }).join('')}</div>`; }
function renderLeadList() { return `<div class="crm2-opp-leads"><div class="crm2-opp-leads-header"><div><strong>Leads e cadastros provisórios</strong><span>Registros comerciais ainda não convertidos.</span></div>${crm2OportunidadesState.canCreate ? '<button class="save-btn" type="button" onclick="crm2OportunidadesOpenLeadCreate()">+ Novo lead</button>' : ''}</div><div class="ar-crm-phase1-table-wrap crm2-opp-table-wrap"><table class="ar-crm-phase1-table crm2-opp-table"><thead><tr><th>Identificação</th><th>Tipo</th><th>Origem</th><th>Status</th><th>Responsável</th><th>Atualizado</th></tr></thead><tbody>${crm2OportunidadesState.leads.map((lead) => `<tr><td><strong>${escapeOpp(leadLabel(lead))}</strong><small>${escapeOpp(lead.cpf ? maskCpfOpp(lead.cpf) : lead.cnpj ? maskCnpjOpp(lead.cnpj) : lead.email || 'Identificação provisória')}</small></td><td>${escapeOpp(lead.tipo)}</td><td>${escapeOpp(lead.origem)}</td><td>${stagePillOpp(lead.status)}</td><td>${escapeOpp(lead.responsavel)}</td><td>${escapeOpp(dateTimeOpp(lead.atualizadoEm))}</td></tr>`).join('')}</tbody></table></div></div>`; }
function renderOppList() { const filtered = filteredOpps(); const totalPages = Math.max(1, Math.ceil(filtered.length / crm2OportunidadesState.perPage)); crm2OportunidadesState.page = Math.min(Math.max(1, crm2OportunidadesState.page), totalPages); const pageItems = filtered.slice((crm2OportunidadesState.page - 1) * crm2OportunidadesState.perPage, crm2OportunidadesState.page * crm2OportunidadesState.perPage); const content = crm2OportunidadesState.listState !== 'normal' ? renderOppState() : pageItems.length ? (crm2OportunidadesState.viewMode === 'kanban' ? renderOppKanban(filtered) : `${renderOppTable(pageItems)}<div class="crm2-opp-pagination"><span>Página <strong>${crm2OportunidadesState.page}</strong> de <strong>${totalPages}</strong> · ${filtered.length} oportunidade(s)</span><div><button class="secondary-btn" type="button" onclick="crm2OportunidadesSetPage(${crm2OportunidadesState.page - 1})" ${crm2OportunidadesState.page <= 1 ? 'disabled' : ''}>Anterior</button><button class="secondary-btn" type="button" onclick="crm2OportunidadesSetPage(${crm2OportunidadesState.page + 1})" ${crm2OportunidadesState.page >= totalPages ? 'disabled' : ''}>Próxima</button></div></div>`) : `<div class="crm2-pessoas-state" role="status"><strong>${crm2OportunidadesState.opportunities.length ? 'Nenhum resultado encontrado.' : 'Nenhuma oportunidade cadastrada.'}</strong><span>Ajuste os filtros ou cadastre uma nova oportunidade.</span><button class="secondary-btn" type="button" onclick="crm2OportunidadesClearFilters()">Limpar filtros</button></div>`; return `<section class="admin-panel crm2-pessoas-page crm2-oportunidades-page" data-crm2-oportunidades="true" aria-labelledby="crm2-opp-title"><div class="admin-panel-header crm2-pessoas-list-header"><div><span class="ar-crm-phase1-kicker">ROTA 205 · CRM 2.0</span><h3 id="crm2-opp-title">Oportunidades</h3><p class="crm2-opp-subtitle">Gestão mockada de leads, negociações e itens comerciais.</p></div><div class="crm2-pessoas-header-actions"><button class="secondary-btn" type="button" onclick="navegarParaCrm2Rota('200')">Voltar ao CRM 2.0</button></div></div><div class="crm2-opp-section-tabs" role="tablist" aria-label="Seção comercial"><button class="${crm2OportunidadesState.section === 'opportunities' ? 'active' : ''}" type="button" role="tab" aria-selected="${crm2OportunidadesState.section === 'opportunities'}" onclick="crm2OportunidadesSetSection('opportunities')">Oportunidades</button><button class="${crm2OportunidadesState.section === 'leads' ? 'active' : ''}" type="button" role="tab" aria-selected="${crm2OportunidadesState.section === 'leads'}" onclick="crm2OportunidadesSetSection('leads')">Leads</button></div>${crm2OportunidadesState.section === 'leads' ? renderLeadList() : `${renderOppFilters()}${content}`}</section>`; }

function renderLeadForm() { const draft = crm2OportunidadesState.draft; const matches = crm2OportunidadesState.duplicateMatches; return `<section class="admin-panel crm2-pessoas-page crm2-oportunidades-page" data-crm2-oportunidades="true" aria-labelledby="crm2-lead-form-title"><div class="admin-panel-header"><div><span class="ar-crm-phase1-kicker">ROTA 205 · LEAD PROVISÓRIO</span><h3 id="crm2-lead-form-title">Novo lead</h3><p class="crm2-opp-subtitle">Faça a busca inicial para evitar duplicidades antes de cadastrar.</p></div><button class="secondary-btn" type="button" onclick="crm2OportunidadesBack()">Voltar</button></div><form class="crm2-opp-duplicate-check" onsubmit="crm2OportunidadesCheckDuplicate(event)"><label><span>Buscar cadastro existente</span><input class="config-input" name="duplicateQuery" value="${attrOpp(crm2OportunidadesState.duplicateQuery)}" placeholder="CPF, CNPJ, nome, razão social ou e-mail"></label><button class="secondary-btn" type="submit">Verificar duplicidade</button></form>${matches.length ? `<div class="crm2-opp-duplicate-alert" role="alert"><strong>Possíveis registros encontrados</strong><span>Revise antes de criar um lead provisório.</span><div>${matches.map((match) => `<article><strong>${escapeOpp(upperOpp(match.nome || match.razaoSocial))}</strong><small>${escapeOpp(match.origemRegistro)} · ${escapeOpp(match.cpf ? maskCpfOpp(match.cpf) : match.cnpj ? maskCnpjOpp(match.cnpj) : match.email || '')}</small><button class="secondary-btn" type="button" onclick="crm2OportunidadesOpenExisting('${attrOpp(match.id)}','${attrOpp(match.origemRegistro)}')">Abrir registro</button></article>`).join('')}</div>${!crm2OportunidadesState.allowDuplicate ? '<button class="secondary-btn" type="button" onclick="crm2OportunidadesAllowDuplicate()">Continuar como lead provisório</button>' : '<small>Continuação como lead provisório confirmada.</small>'}</div>` : crm2OportunidadesState.duplicateChecked ? '<p class="crm2-opp-duplicate-ok" role="status">Nenhuma duplicidade encontrada na base mockada.</p>' : ''}<form class="crm2-opp-form" onsubmit="crm2OportunidadesSaveLead(event)"><div class="crm2-opp-form-grid">${oppField({ label: 'Tipo', name: 'tipo', value: draft.tipo || 'provisorio', type: 'select', options: ['PF', 'PJ', 'provisorio'], required: true })}${oppField({ label: 'Nome ou razão social', name: 'nome', value: draft.nome || draft.razaoSocial, required: true })}${oppField({ label: 'CPF/CNPJ', name: 'documento', value: draft.cpf || draft.cnpj })}${oppField({ label: 'E-mail', name: 'email', value: draft.email, type: 'email' })}${oppField({ label: 'Telefone', name: 'telefone', value: draft.telefone })}${oppField({ label: 'Origem', name: 'origem', value: draft.origem || 'Atendimento interno', type: 'select', options: OPPORTUNITY_SOURCES, required: true })}${oppField({ label: 'Responsável', name: 'responsavel', value: draft.responsavel || 'Ana Martins', required: true })}${oppField({ label: 'Observações', name: 'observacoes', value: draft.observacoes, type: 'textarea', wide: true })}</div><div class="crm2-opp-form-actions"><button class="secondary-btn" type="button" onclick="crm2OportunidadesBack()">Cancelar</button><button class="save-btn" type="submit" ${matches.length && !crm2OportunidadesState.allowDuplicate ? 'disabled' : ''}>Salvar lead provisório</button></div></form></section>`; }
function renderNextContactFieldsOpp(draft, formId = '') { return `${oppField({ label: 'Próximo contato', name: 'proximoContatoData', value: draft.proximoContatoData, type: 'date', formId })}${oppField({ label: 'Horário do próximo contato', name: 'proximoContatoHora', value: draft.proximoContatoHora, type: 'time', formId })}`; }
function oppField({ label, name, value = '', type = 'text', options = [], required = false, wide = false, formId = '' }) { const error = crm2OportunidadesState.errors[name] || ''; const id = `crm2-opp-${name}`; const eventAttr = name === 'pfId' ? ' onchange="crm2OportunidadesSelectPf(this.value)"' : name === 'motivoPerda' ? ' onchange="crm2OportunidadesRefreshDerivedStatus()"' : name === 'documento' ? ' oninput="crm2OportunidadesFormatDocument(this)"' : name === 'telefone' ? ' oninput="crm2OportunidadesFormatPhone(this)"' : name === 'nome' ? ' oninput="crm2OportunidadesFormatName(this)"' : ''; const formAttr = formId ? ` form="${formId}"` : ''; const common = `id="${id}" class="config-input" name="${name}"${eventAttr}${formAttr} ${required ? 'required' : ''} aria-invalid="${error ? 'true' : 'false'}"`; const normalizedOptions = options.map((item) => typeof item === 'string' ? { value: item, label: item } : item); const input = type === 'textarea' ? `<textarea ${common} rows="4">${escapeOpp(value)}</textarea>` : type === 'select' ? `<select ${common}><option value="">Selecione</option>${normalizedOptions.map((item) => `<option value="${attrOpp(item.value)}" ${String(item.value) === String(value) ? 'selected' : ''}>${escapeOpp(item.label)}</option>`).join('')}</select>` : `<input ${common} type="${type}" value="${attrOpp(name === 'documento' ? maskDocumentOpp(value) : name === 'telefone' ? maskPhoneOpp(value) : name === 'nome' ? upperOpp(value) : value)}">`; const field = `<label class="${wide ? 'is-wide' : ''}"><span>${escapeOpp(label)}${required ? ' *' : ''}</span>${input}${error ? `<small class="crm2-field-error">${escapeOpp(error)}</small>` : ''}</label>`; return name === 'previsaoFechamento' ? `${field}${renderNextContactFieldsOpp(crm2OportunidadesState.draft, formId)}` : field; }


